// Recordatorio de la visita (HU0003-1.0, D4, ADR-16 «seguimiento-recordatorios»): un ítem por cada cita de
// GET /internal/recordatorios/pendientes (citas reservadas dentro de la ventana [fecha_hora − RECORDATORIO_VISITA_HORAS,
// fecha_hora) sin recordatorio, y recordatorios cuyo último intento lleva más de 10 min pendiente). Sin nodos Wait: el
// recordatorio queda «programado» por los datos. Si no hay pendientes no sale ningún ítem y la ejecución termina aquí.
// Solo lleva id_cita (A3).
const salida = [];
$input.all().forEach((item, indice) => {
  const citas = Array.isArray(item.json?.citas) ? item.json.citas : [];
  for (const c of citas) {
    if (Number.isSafeInteger(c?.id_cita) && c.id_cita > 0 && c.id_cita <= 2147483647) {
      salida.push({ json: { id_cita: c.id_cita }, pairedItem: { item: indice } });
    }
  }
});
return salida;

// Decide qué hace seguimiento-recordatorios con lo que devolvió notificacion-multicanal para cada recordatorio de la
// visita (HU0003-1.0, D4). Sigue ADR-07 «Fallos de los avisos de la visita»: la clasificación de D7, sin rebote ni
// transición (P-j); es la misma lógica de «Clasificar resultado» de agendamiento.
// Entrada: un ítem por aviso, emparejado con su reserva de la salida «reservado» de «¿Reserva hecha?» por el pairedItem
// que pone Execute Workflow (el subflujo corre una vez por ítem); si falta, por la posición. Es el resultado del
// subflujo, { id_expediente, correo: { estado_envio, id_notificacion }, whatsapp }, o, si falló, { error: "<mensaje>" }
// (Execute Workflow con onError continueRegularOutput, C9).
//   enviado   <- correo.estado_envio = enviado: el subflujo ya cerró la fila                    -> termina
//   fallido   <- correo.estado_envio = fallido: rechazo permanente del destinatario; con la fila reservada el subflujo
//                no la cierra                      (motivo rechazo_destinatario) -> PATCH fallido y termina sin error
//             <- error «notificacion-multicanal: entrada inválida…» (400): un defecto, la entrada la arma la API
//                                                  (motivo entrada_invalida)     -> PATCH fallido y Stop and Error
//   pendiente <- correo.estado_envio = pendiente (error técnico de SMTP, o un 5xx que no es rechazo permanente), un 502,
//                un 500 o cualquier otro error: resultado desconocido (R22), nunca se marca fallido
//                                                  -> sin PATCH y Stop and Error; el barrido lo retoma a los 10 min
//                                                     con un intento nuevo (una fila por intento, ADR-07)
// Lo que no se reconoce cae en pendiente.
// A3 (D3): la salida lleva solo la acción, el motivo y los ids de la cita, el expediente y la notificación. Nunca el
// asunto ni el cuerpo de la reserva, ni el mensaje del error del subflujo.
const ENTRADA_INVALIDA = 'notificacion-multicanal: entrada inválida';
const reservas = $('¿Reserva hecha?').all(0);

const clasificar = (resultado) => {
  if (resultado.error !== undefined) {
    const mensaje = typeof resultado.error === 'string' ? resultado.error : String(resultado.error?.message ?? '');
    return mensaje.startsWith(ENTRADA_INVALIDA)
      ? { accion: 'fallido', motivo: 'entrada_invalida' }
      : { accion: 'pendiente', motivo: 'notificacion_no_disponible' };
  }
  switch (resultado.correo?.estado_envio) {
    case 'enviado':
      return { accion: 'enviado', motivo: 'enviado' };
    case 'fallido':
      return { accion: 'fallido', motivo: 'rechazo_destinatario' };
    case 'pendiente':
      return { accion: 'pendiente', motivo: 'smtp_pendiente' };
    default:
      return { accion: 'pendiente', motivo: 'resultado_desconocido' };
  }
};

return $input.all().map((item, indice) => {
  const reserva = reservas[item.pairedItem?.item ?? indice]?.json?.body ?? {};
  return {
    json: {
      ...clasificar(item.json ?? {}),
      id_cita: reserva.id_cita ?? null,
      id_expediente: reserva.id_expediente ?? null,
      id_notificacion: reserva.id_notificacion ?? null,
    },
    pairedItem: { item: indice },
  };
});

// Revisión diaria del seguimiento (HU0018-1.0 recordatorio a las 48 h, R20; HU0018-2.0 caducidad, R21; ADR-16): un ítem por
// cada expediente de GET /internal/seguimiento/pendientes, con la acción que le toca: { accion: 'caducidad' | 'recordatorio',
// id_expediente }. Si no hay pendientes no sale ningún ítem y la ejecución termina aquí. Solo lleva ids.
const salida = [];
const valido = (e) => Number.isSafeInteger(e?.id_expediente) && e.id_expediente > 0 && e.id_expediente <= 2147483647;
$input.all().forEach((item, indice) => {
  const pares = [['caducidad', item.json?.caducidades], ['recordatorio', item.json?.recordatorios]];
  for (const [accion, lista] of pares) {
    for (const e of Array.isArray(lista) ? lista : []) {
      if (valido(e)) salida.push({ json: { accion, id_expediente: e.id_expediente }, pairedItem: { item: indice } });
    }
  }
});
return salida;

// Retoma de los avisos del seguimiento (HU0018-1.0 y HU0018-2.0; ADR-07, ADR-16): un ítem por cada aviso de
// GET /internal/seguimiento/avisos-pendientes (el último intento sigue pendiente hace más de 10 min). Si no hay pendientes
// no sale ningún ítem y la ejecución termina aquí. Solo lleva { id_expediente, tipo_evento }.
const salida = [];
$input.all().forEach((item, indice) => {
  const avisos = Array.isArray(item.json?.avisos) ? item.json.avisos : [];
  for (const a of avisos) {
    const idValido = Number.isSafeInteger(a?.id_expediente) && a.id_expediente > 0 && a.id_expediente <= 2147483647;
    if (idValido && typeof a.tipo_evento === 'string' && /^[a-z0-9_]{1,60}$/.test(a.tipo_evento)) {
      salida.push({ json: { id_expediente: a.id_expediente, tipo_evento: a.tipo_evento }, pairedItem: { item: indice } });
    }
  }
});
return salida;

// Avisos reservados del seguimiento (HU0018-1.0 recordatorio a las 48 h; HU0018-2.0 caducidad con dos avisos, a la familia y al
// buzón de admisión): un ítem por cada aviso de la reserva. La caducidad responde { id_expediente, avisos: [...] } y el
// recordatorio y la retoma, un solo aviso { id_expediente, id_notificacion, tipo_evento, asunto, cuerpo }. El contacto lo
// resuelve la API por id_notificacion. Lo que no tiene la forma esperada se descarta.
const salida = [];
const entero = (v) => Number.isSafeInteger(v) && v > 0 && v <= 2147483647;
$input.all().forEach((item, indice) => {
  const cuerpo = item.json?.body ?? {};
  const avisos = Array.isArray(cuerpo.avisos) ? cuerpo.avisos : [cuerpo];
  for (const a of avisos) {
    if (entero(a?.id_expediente) && entero(a?.id_notificacion) && typeof a.tipo_evento === 'string' && typeof a.asunto === 'string' && typeof a.cuerpo === 'string') {
      salida.push({
        json: { id_expediente: a.id_expediente, id_notificacion: a.id_notificacion, tipo_evento: a.tipo_evento, asunto: a.asunto, cuerpo: a.cuerpo },
        pairedItem: { item: indice },
      });
    }
  }
});
return salida;

// Decide qué hace seguimiento-recordatorios con lo que devolvió notificacion-multicanal para cada aviso del seguimiento
// (HU0018-1.0 recordatorio a las 48 h; HU0018-2.0 caducidad). Sigue ADR-07 «Fallos de los avisos de la visita»: la
// clasificación de D7, sin rebote ni transición (P-j).
// Entrada: un ítem por aviso, emparejado con su reserva («Un ítem por aviso») por el pairedItem que pone Execute Workflow
// (el subflujo corre una vez por ítem); si falta, por la posición. Es el resultado del subflujo,
// { id_expediente, correo: { estado_envio, id_notificacion }, whatsapp }, o, si falló, { error: "<mensaje>" }
// (Execute Workflow con onError continueRegularOutput, C9).
//   enviado   <- correo.estado_envio = enviado: el subflujo ya cerró la fila                    -> termina
//   fallido   <- correo.estado_envio = fallido: rechazo permanente del destinatario             (rechazo_destinatario) -> PATCH fallido
//             <- error «notificacion-multicanal: entrada inválida…» (400): un defecto           (entrada_invalida)     -> PATCH fallido
//   pendiente <- error técnico de SMTP, 5xx que no es rechazo, 502, 500 u otro error: resultado desconocido (R22), nunca
//                se marca fallido -> sin PATCH y registro del fallo; la retoma de cada minuto lo reintenta a los 10 min con
//                un intento nuevo (una fila por intento, ADR-07)
// Lo que no se reconoce cae en pendiente.
// La salida lleva solo la acción, el motivo y los ids del expediente y la notificación. Nunca el asunto ni el cuerpo del
// aviso ni el mensaje del error del subflujo (C11).
const ENTRADA_INVALIDA = 'notificacion-multicanal: entrada inválida';
const reservas = $('Un ítem por aviso').all();

const clasificar = (resultado) => {
  if (resultado.error !== undefined) {
    const mensaje = typeof resultado.error === 'string' ? resultado.error : String(resultado.error?.message ?? '');
    return mensaje.startsWith(ENTRADA_INVALIDA)
      ? { accion: 'fallido', motivo: 'entrada_invalida' }
      : { accion: 'pendiente', motivo: 'notificacion_no_disponible' };
  }
  switch (resultado.correo?.estado_envio) {
    case 'enviado':
      return { accion: 'enviado', motivo: 'enviado' };
    case 'fallido':
      return { accion: 'fallido', motivo: 'rechazo_destinatario' };
    case 'pendiente':
      return { accion: 'pendiente', motivo: 'smtp_pendiente' };
    default:
      return { accion: 'pendiente', motivo: 'resultado_desconocido' };
  }
};

return $input.all().map((item, indice) => {
  const reserva = reservas[item.pairedItem?.item ?? indice]?.json ?? {};
  return {
    json: {
      ...clasificar(item.json ?? {}),
      id_expediente: reserva.id_expediente ?? null,
      id_notificacion: reserva.id_notificacion ?? null,
    },
    pairedItem: { item: indice },
  };
});

// Rama de error de «Reservar seguimiento» en seguimiento-recordatorios (HU0018-1.0 y HU0018-2.0, C2 y C41-4): un expediente que falla no frena a los demás del barrido, y este nodo prepara el registro del fallo. Emite solo los
// identificadores que admite POST /internal/errores-flujo: el flujo, el nodo y el id de esta ejecución. NO lee el ítem de
// entrada: trae el mensaje del error, el asunto o el cuerpo del aviso (C11). Un ítem de salida por cada expediente que falló.
const id = String($execution?.id ?? '');
const id_ejecucion = /^[0-9A-Za-z-]{1,40}$/.test(id) ? id : 'sin-id';

return $input.all().map((_item, indice) => ({
  json: { flujo: 'seguimiento-recordatorios', nodo: 'Reservar seguimiento', id_ejecucion },
  pairedItem: { item: indice },
}));

// Rama de error de «Reservar aviso» en seguimiento-recordatorios (HU0018-1.0 y HU0018-2.0, C2 y C41-4): un expediente que falla no frena a los demás del barrido, y este nodo prepara el registro del fallo. Emite solo los
// identificadores que admite POST /internal/errores-flujo: el flujo, el nodo y el id de esta ejecución. NO lee el ítem de
// entrada: trae el mensaje del error, el asunto o el cuerpo del aviso (C11). Un ítem de salida por cada aviso que falló.
const id = String($execution?.id ?? '');
const id_ejecucion = /^[0-9A-Za-z-]{1,40}$/.test(id) ? id : 'sin-id';

return $input.all().map((_item, indice) => ({
  json: { flujo: 'seguimiento-recordatorios', nodo: 'Reservar aviso', id_ejecucion },
  pairedItem: { item: indice },
}));

// Rama de error de «Enviar aviso» en seguimiento-recordatorios (HU0018-1.0 y HU0018-2.0, C2 y C41-4): un expediente que falla no frena a los demás del barrido, y este nodo prepara el registro del fallo. Emite solo los
// identificadores que admite POST /internal/errores-flujo: el flujo, el nodo y el id de esta ejecución. NO lee el ítem de
// entrada: trae el mensaje del error, el asunto o el cuerpo del aviso (C11). Un ítem de salida por cada aviso que quedó pendiente o no se pudo cerrar.
const id = String($execution?.id ?? '');
const id_ejecucion = /^[0-9A-Za-z-]{1,40}$/.test(id) ? id : 'sin-id';

return $input.all().map((_item, indice) => ({
  json: { flujo: 'seguimiento-recordatorios', nodo: 'Enviar aviso', id_ejecucion },
  pairedItem: { item: indice },
}));
